thin_tier1 <- function(tier1, cfg, template=NULL) { tier1$.row_id <- seq_len(nrow(tier1)); pos <- tier1$Yi==1; if (!isTRUE(cfg$tier1_thinning$enabled)) return(list(retained=tier1,excluded=tier1[0,],audit=data.frame(excluded=0))); if (is.null(template)) stop("Thinning requires a template raster"); tier1$.cell_id <- terra::cellFromXY(template, as.matrix(tier1[c("x","y")])); set.seed(cfg$tier1_thinning$seed); keep <- tier1[pos,] |> dplyr::group_by(epiyear,epiweek,.cell_id) |> dplyr::slice_sample(n=1) |> dplyr::ungroup(); excluded <- dplyr::anti_join(tier1[pos,],keep[".row_id"],by=".row_id"); list(retained=dplyr::bind_rows(keep,tier1[!pos,]),excluded=excluded,audit=data.frame(input_positive=sum(pos),retained_positive=nrow(keep),excluded_positive=nrow(excluded))) }
build_tier1 <- function(observations, integration, time_index) { q <- tidyr::crossing(integration,time_index); q$Yi <- 0; q$sc_Exp <- q$area %||% 1; p <- observations; p$Yi <- 1; p$sc_Exp <- 0.0001; dplyr::bind_rows(p,q) }
build_tier2 <- function(observations, support, time_index) { pts <- sf::st_as_sf(observations,coords=c("x","y"),crs=sf::st_crs(support$domain)); hit <- sf::st_within(pts,support$mesh_polygons); observations$poly_id <- vapply(hit,function(i) if(length(i)) support$mesh_polygons$poly_id[i[1]] else NA_integer_,integer(1)); cent <- sf::st_coordinates(sf::st_centroid(support$mesh_polygons)); base <- data.frame(poly_id=support$mesh_polygons$poly_id,x=cent[,1],y=cent[,2],area=support$mesh_polygons$area); counts <- observations |> dplyr::count(poly_id,epiyear,epiweek,name="n_points"); out <- tidyr::crossing(base,time_index) |> dplyr::left_join(counts,by=c("poly_id","epiyear","epiweek")); out$n_points[is.na(out$n_points)] <- 0; out$Yi <- out$n_points; out$sc_Exp <- out$area; out }
build_prediction_grid <- function(support,time_index) { pts <- sf::st_coordinates(sf::st_centroid(support$mesh_polygons)); cells <- data.frame(cell_id=support$mesh_polygons$poly_id,x=pts[,1],y=pts[,2]); tidyr::crossing(cells,time_index) |> dplyr::mutate(space_time_id=paste(cell_id,time_index,sep="_")) }
assemble_model_inputs <- function(tier1,tier2,prediction_grid,support,time_index,transformations,audits,cfg,excluded=tier1[0,]) list(tier1=tier1,tier2=tier2,prediction_grid=prediction_grid,mesh=support$mesh,mesh_polygons=support$mesh_polygons,time_index=time_index,transformations=transformations,excluded_detections=excluded,observation_audit=audits$observation,covariate_audit=audits$covariate,configuration=cfg,provenance=list(timestamp=as.character(Sys.time()),git_commit=NA_character_,R=R.version.string,seed=cfg$project$seed))
